1→{
  "name": "exchange-backend",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=20.11"
  },
  "scripts": {
10→    "build": "tsc -p tsconfig.json",
    "start": "node --env-file-if-exists=.env dist/main.js",
    "dev": "node --env-file-if-exists=.env --import tsx src/main.ts",
    "test": "vitest run",
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "dependencies": {
    "@noble/curves": "^2.4.0",
    "@noble/hashes": "^2.4.0",
    "better-sqlite3": "^13.0.3",
20→    "fastify": "^5.12.3"
  },
  "devDependencies": {
    "@types/better-sqlite3": "^9.6.0",
    "@types/node": "^26.4.1",
    "tsx": "^4.23.13",
    "typescript": "^7.0.2",
    "vitest": "^3.2.7"
  }
}
30→

1→/**
 * Punto de entrada del backend.
 *
 * Secuencia de arranque:
 *   1. Cargar y validar configuración (un TTL de sesión fuera de [60, 86400] impide arrancar,
 *      HU-01-02 RN-3).
 *   2. Abrir la base persistente, provisionar/cargar el seed de la wallet HD y verificar su
 *      integridad (HU-06-01 RN-8/RN-10/RN-11): ante cualquier fallo crítico el proceso
 *      **aborta con código de salida distinto de cero** e imprime el `code` del catálogo en
10→ *      `stderr`, sin regenerar el seed ni filtrar material secreto.
 *   3. Levantar el servidor HTTP.
 */
import { loadConfig, ConfigError } from './config/index.js';
import { createRuntime } from './runtime.js';
import { SeedProvisioningError } from './wallet/seed-store.js';

const CHAIN_PROBE_INTERVAL_MS = 30_000;

function abort(code: string, message: string): never {
20→  process.stderr.write(`[FATAL] code=${code} ${message}\n`);
  process.exit(1);
}

async function main(): Promise<void> {
  let config;
  try {
    config = loadConfig();
  } catch (error) {
    if (error instanceof ConfigError) abort('VALIDATION_ERROR', error.message);
30→    throw error;
  }

  let runtime;
  try {
    runtime = createRuntime(config);
  } catch (error) {
    if (error instanceof SeedProvisioningError) abort(error.code, error.message);
    abort(
      'INTERNAL_ERROR',
40→      `Fallo no clasificado durante el arranque: ${error instanceof Error ? error.message : 'desconocido'}`,
    );
  }
  process.stdout.write('[wallet] seed HD disponible y verificado (cifrado en reposo)\n');

  const status = await runtime.refreshChainStatus();
  if (status.status === 'MISMATCH') {
    process.stderr.write(
      `[chain] code=CHAIN_ID_MISMATCH el nodo JSON-RPC configurado reporta chainId ` +
        `${status.chainId}; se esperaba ${status.expected} (Sepolia).\n`,
50→    );
  }
  const probeTimer = setInterval(() => {
    void runtime.refreshChainStatus();
  }, CHAIN_PROBE_INTERVAL_MS);
  probeTimer.unref();

  const shutdown = async (signal: string): Promise<void> => {
    runtime.app.log.info(`recibida señal ${signal}: cerrando`);
    clearInterval(probeTimer);
60→    await runtime.close();
    process.exit(0);
  };
  process.on('SIGINT', () => void shutdown('SIGINT'));
  process.on('SIGTERM', () => void shutdown('SIGTERM'));

  await runtime.app.listen({ host: config.host, port: config.port });
}

main().catch((error: unknown) => {
70→  process.stderr.write(
    `[FATAL] code=INTERNAL_ERROR el servicio no pudo arrancar: ${
      error instanceof Error ? error.message : String(error)
    }\n`,
  );
  process.exit(1);
});

1→/**
 * BIP-39 — mnemonic code for generating deterministic keys.
 *
 * Fuente normativa: BIP-39 («Generating the mnemonic» y «From mnemonic to seed»).
 * Spec del proyecto: HU-06-01 RN-1 (entropía de CSPRNG, 256 bits ⇒ 24 palabras),
 * RN-2 (normalización NFKD + validación de longitud, wordlist y checksum, en ese orden),
 * RN-3 (seed binaria por PBKDF2-HMAC-SHA512, 2048 iteraciones, 64 bytes) y
 * RN-7 (determinismo: la seed es función pura de `(mnemonic, passphrase)`).
 *
10→ * Custodia (HU-06-01 RN-5): ninguna función de este módulo logea ni serializa el mnemonic
 * ni la seed; los mensajes de error nunca incluyen material secreto.
 */
import { randomBytes } from 'node:crypto';
import { pbkdf2 } from '@noble/hashes/pbkdf2.js';
import { sha256, sha512 } from '@noble/hashes/sha2.js';
import { ENGLISH_WORDLIST, WORDLIST_INDEX } from './wordlist.js';

/** Longitudes de entropía admitidas por BIP-39 (ENT ∈ [128, 256], múltiplo de 32 bits). */
const ALLOWED_ENTROPY_BITS: readonly number[] = [128, 160, 192, 224, 256];
20→
/** Entropía fijada por el proyecto (HU-06-01 RN-1): 256 bits ⇒ 24 palabras. */
export const PROJECT_ENTROPY_BITS = 256;

/** Longitud de mnemonic exigida por la política del proyecto (HU-06-01 RN-2.a). */
export const PROJECT_MNEMONIC_WORDS = 24;

/** Parámetros de PBKDF2 fijados por BIP-39 (HU-06-01 RN-3). */
export const PBKDF2_ITERATIONS = 2048;
export const SEED_BYTES = 64;
30→
/** Prefijo del salt de PBKDF2 según BIP-39: `"mnemonic" + passphrase`. */
const SALT_PREFIX = 'mnemonic';

const utf8 = new TextEncoder();

export type MnemonicValidation =
  | { ok: true }
  | { ok: false; reason: 'LENGTH' | 'WORDLIST' | 'CHECKSUM' };

40→/**
 * Normalización Unicode NFKD del mnemonic (BIP-39, «From mnemonic to seed»: la frase se usa
 * como password de PBKDF2 **en UTF-8 NFKD**, sin ninguna otra transformación).
 *
 * Es **la única** normalización que se aplica antes de derivar la seed (RN-3): no se
 * colapsan ni recortan separadores, porque eso cambiaría el password de PBKDF2 y la seed
 * resultante diferiría de la de cualquier implementación literal del estándar.
 *
 * Para el wordlist inglés (ASCII puro) la NFKD es un no-op, pero se aplica de forma genérica
 * para ser robusto ante mnemonics importados de sistemas con otra normalización.
50→ */
export function normalizeMnemonic(mnemonic: string): string {
  return mnemonic.normalize('NFKD');
}

/**
 * Forma **canónica para validar** (HU-06-01 RN-2): NFKD + separadores colapsados a un único
 * espacio y sin espacios de borde. Se usa exclusivamente para partir la frase en palabras y
 * verificar longitud/wordlist/checksum; **nunca** como entrada de PBKDF2.
 */
60→export function canonicalMnemonicForValidation(mnemonic: string): string {
  return normalizeMnemonic(mnemonic).trim().replace(/\s+/gu, ' ');
}

/** Normaliza la passphrase a NFKD (BIP-39, «From mnemonic to seed»). */
export function normalizePassphrase(passphrase: string): string {
  return passphrase.normalize('NFKD');
}

/** Divide un mnemonic ya normalizado en sus palabras. */
70→function splitWords(normalized: string): string[] {
  return normalized.length === 0 ? [] : normalized.split(' ');
}

/** Representación binaria big-endian de un buffer, un carácter '0'/'1' por bit. */
function bytesToBinary(bytes: Uint8Array): string {
  let bits = '';
  for (const byte of bytes) bits += byte.toString(2).padStart(8, '0');
  return bits;
}
80→
/** Inversa de {@link bytesToBinary}; `bits.length` debe ser múltiplo de 8. */
function binaryToBytes(bits: string): Uint8Array {
  const out = new Uint8Array(bits.length / 8);
  for (let i = 0; i < out.length; i += 1) {
    out[i] = Number.parseInt(bits.slice(i * 8, i * 8 + 8), 2);
  }
  return out;
}

90→/**
 * Checksum BIP-39: los primeros `ENT / 32` bits de `SHA-256(entropía)`.
 * (HU-06-01 RN-2.c)
 */
function checksumBits(entropy: Uint8Array): string {
  const checksumLength = (entropy.length * 8) / 32;
  return bytesToBinary(sha256(entropy)).slice(0, checksumLength);
}

/**
100→ * Codifica entropía como mnemonic BIP-39 (sección «Generating the mnemonic»):
 * entropía ‖ checksum, partido en grupos de 11 bits que indexan el wordlist inglés.
 * (HU-06-01 RN-1)
 */
export function entropyToMnemonic(entropy: Uint8Array): string {
  const entropyBits = entropy.length * 8;
  if (!ALLOWED_ENTROPY_BITS.includes(entropyBits)) {
    throw new Error(
      `Entropía BIP-39 inválida: ${entropyBits} bits (admitidos: ${ALLOWED_ENTROPY_BITS.join(', ')}).`,
    );
110→  }
  const bits = bytesToBinary(entropy) + checksumBits(entropy);
  const words: string[] = [];
  for (let i = 0; i < bits.length; i += 11) {
    const index = Number.parseInt(bits.slice(i, i + 11), 2);
    const word = ENGLISH_WORDLIST[index];
    // Invariante: el wordlist tiene exactamente 2048 entradas y 11 bits ⇒ índice < 2048.
    if (word === undefined) throw new Error('Índice fuera del wordlist BIP-39.');
    words.push(word);
  }
120→  return words.join(' ');
}

/**
 * Genera un mnemonic BIP-39 nuevo a partir de entropía del CSPRNG del sistema operativo
 * (`crypto.randomBytes`). Por defecto 256 bits ⇒ 24 palabras (HU-06-01 RN-1).
 */
export function generateMnemonic(entropyBits: number = PROJECT_ENTROPY_BITS): string {
  if (!ALLOWED_ENTROPY_BITS.includes(entropyBits)) {
    throw new Error(
130→      `Entropía BIP-39 inválida: ${entropyBits} bits (admitidos: ${ALLOWED_ENTROPY_BITS.join(', ')}).`,
    );
  }
  return entropyToMnemonic(new Uint8Array(randomBytes(entropyBits / 8)));
}

/**
 * Valida un mnemonic según HU-06-01 RN-2, en este orden estricto:
 *   (a) `LENGTH`   — exactamente 24 palabras (política del proyecto: 256 bits de entropía;
 *                    12/15/18/21 palabras se rechazan aunque su checksum sea válido);
140→ *   (b) `WORDLIST` — todas las palabras pertenecen al wordlist BIP-39 inglés;
 *   (c) `CHECKSUM` — el checksum BIP-39 verifica.
 *
 * Nota de diseño: esta función expresa la **política del proyecto**, no el algoritmo
 * BIP-39 puro. `mnemonicToSeed` es deliberadamente independiente de ella (BIP-39: «la
 * conversión del mnemonic a seed binaria es completamente independiente de la generación
 * de la frase»), de modo que los vectores canónicos de 12 palabras siguen derivando.
 */
export function validateMnemonic(mnemonic: string): MnemonicValidation {
  const words = splitWords(canonicalMnemonicForValidation(mnemonic));
150→
  // (a) longitud
  if (words.length !== PROJECT_MNEMONIC_WORDS) return { ok: false, reason: 'LENGTH' };

  // (b) wordlist
  const indices: number[] = [];
  for (const word of words) {
    const index = WORDLIST_INDEX.get(word);
    if (index === undefined) return { ok: false, reason: 'WORDLIST' };
    indices.push(index);
160→  }

  // (c) checksum
  let bits = '';
  for (const index of indices) bits += index.toString(2).padStart(11, '0');
  const entropyLength = (bits.length * 32) / 33;
  const entropy = binaryToBytes(bits.slice(0, entropyLength));
  if (bits.slice(entropyLength) !== checksumBits(entropy)) {
    return { ok: false, reason: 'CHECKSUM' };
  }
170→
  return { ok: true };
}

/**
 * Deriva la seed binaria de 512 bits (64 bytes), raíz de la wallet BIP-32
 * (HU-06-01 RN-3 / RN-7):
 *
 *   `PBKDF2(HMAC-SHA512, password = mnemonic_NFKD, salt = "mnemonic" + passphrase_NFKD,
 *           iteraciones = 2048, dkLen = 64)`
180→ *
 * Es el **algoritmo BIP-39 puro**: no aplica la política de 24 palabras de
 * {@link validateMnemonic}, por lo que funciona con cualquier mnemonic bien formado
 * (incluidos los vectores canónicos de 12 palabras usados en los known-answer tests).
 */
export function mnemonicToSeed(mnemonic: string, passphrase = ''): Uint8Array {
  const password = utf8.encode(normalizeMnemonic(mnemonic));
  const salt = utf8.encode(SALT_PREFIX + normalizePassphrase(passphrase));
  return pbkdf2(sha512, password, salt, { c: PBKDF2_ITERATIONS, dkLen: SEED_BYTES });
}
190→

1→/**
 * BIP-32 — Hierarchical Deterministic Wallets sobre secp256k1.
 *
 * Fuente normativa: BIP-32 («Master key generation», «Private parent key → private child
 * key», «The key tree»).
 * Spec del proyecto: HU-06-02 RN-1 (clave maestra), RN-3 (CKDpriv hardened/normal),
 * RN-5 (determinismo: función pura de `(seed, path)`) y RN-8 (borde de clave inválida).
 *
 * Custodia (HU-06-02 RN-6): este módulo no logea ni serializa claves privadas.
10→ */
import { secp256k1 } from '@noble/curves/secp256k1.js';
import { primitives } from './primitives.js';

/** Offset de derivación hardened: `0x80000000` = 2³¹ = 2147483648 (HU-06-02 RN-2). */
export const HARDENED_OFFSET = 0x8000_0000;

/** Índice máximo de BIP-32 (2³² − 1). */
const MAX_INDEX = 0xffff_ffff;

20→/** Orden `n` del grupo de secp256k1 (HU-06-02 RN-1). */
export const SECP256K1_ORDER =
  0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141n;

/** Clave usada como key del HMAC en la generación de la clave maestra (BIP-32). */
const MASTER_KEY_SALT = new TextEncoder().encode('Bitcoin seed');

/** Nodo extendido BIP-32: clave privada de 32 bytes + chain code de 32 bytes. */
export interface HdNode {
  privateKey: Uint8Array;
30→  chainCode: Uint8Array;
}

/**
 * Clave hija inválida (BIP-32: `parse256(I_L) >= n` o `k_hijo == 0`; ~2⁻¹²⁷).
 * El estándar indica «proceed with the next value for i»: se señaliza con esta excepción
 * tipada para que el llamador avance al índice siguiente (HU-06-02 RN-8, HU-06-03 RN-1).
 */
export class InvalidChildKeyError extends Error {
  /** Índice BIP-32 (ya resuelto: hardened = valor + 2³¹) del nivel que falló. */
40→  readonly index: number;
  /**
   * Nivel del path (1-based) en el que ocurrió el fallo, o `undefined` si la derivación se
   * hizo fuera de un path (llamada directa a {@link ckdPriv}). Lo completa {@link derivePath}.
   *
   * Es imprescindible para aplicar RN-8 correctamente: BIP-32 dice «proceed with the next
   * value for **i**», donde `i` es el índice **del nivel que falló**. Sólo el último nivel de
   * `m/44'/60'/0'/0/{address_index}` depende del `address_index`; si el fallo ocurre en un
   * nivel intermedio, reintentar con otro `address_index` repite el mismo cómputo HMAC y no
   * puede converger nunca (ver `derivation.ts`).
50→   */
  depth: number | undefined;

  constructor(index: number, reason: string, depth?: number) {
    super(`Clave hija BIP-32 inválida en el índice ${index}: ${reason}.`);
    this.name = 'InvalidChildKeyError';
    this.index = index;
    this.depth = depth;
  }
}
60→
/** Clave maestra inválida (`parse256(I_L) == 0` o `>= n`). Condición no recuperable. */
export class InvalidMasterKeyError extends Error {
  constructor(reason: string) {
    super(`Clave maestra BIP-32 inválida: ${reason}.`);
    this.name = 'InvalidMasterKeyError';
  }
}

/** `parse256`: interpreta 32 bytes big-endian como entero. */
70→function parse256(bytes: Uint8Array): bigint {
  let value = 0n;
  for (const byte of bytes) value = (value << 8n) | BigInt(byte);
  return value;
}

/** `ser256`: serializa un entero como 32 bytes big-endian. */
function ser256(value: bigint): Uint8Array {
  const out = new Uint8Array(32);
  let rest = value;
80→  for (let i = 31; i >= 0; i -= 1) {
    out[i] = Number(rest & 0xffn);
    rest >>= 8n;
  }
  return out;
}

/** `ser32`: serializa un entero de 32 bits como 4 bytes big-endian. */
function ser32(value: number): Uint8Array {
  const out = new Uint8Array(4);
90→  new DataView(out.buffer).setUint32(0, value, false);
  return out;
}

/** `serP(point(k))`: clave pública secp256k1 comprimida (33 bytes), usada por CKDpriv normal. */
function serializedPoint(privateKey: Uint8Array): Uint8Array {
  return secp256k1.getPublicKey(privateKey, true);
}

/** Clave pública secp256k1 **sin comprimir**: 65 bytes, prefijo `0x04` ‖ X ‖ Y. */
100→export function publicKeyUncompressed(privateKey: Uint8Array): Uint8Array {
  return secp256k1.getPublicKey(privateKey, false);
}

/**
 * Coordenadas de la clave pública secp256k1: 64 bytes `X ‖ Y` (descartando el prefijo
 * `0x04`). Es la entrada de Keccak-256 para computar la dirección (HU-06-02 RN-4).
 */
export function publicKeyXY(privateKey: Uint8Array): Uint8Array {
  return publicKeyUncompressed(privateKey).slice(1);
110→}

/** Ejecuta HMAC-SHA512 vía el objeto `primitives` (stubbeable, ver AT-06-02-08). */
function hmac512(key: Uint8Array, data: Uint8Array): { left: Uint8Array; right: Uint8Array } {
  const I = primitives.hmacSha512(key, data);
  if (I.length !== 64) {
    throw new Error(`HMAC-SHA512 devolvió ${I.length} bytes; se esperaban 64.`);
  }
  return { left: I.slice(0, 32), right: I.slice(32, 64) };
}
120→
/**
 * Clave maestra BIP-32 desde la seed binaria (HU-06-02 RN-1):
 * `I = HMAC-SHA512(key = "Bitcoin seed", data = seed)`, con `I_L` = clave privada maestra
 * e `I_R` = chain code maestro. Se valida `1 <= parse256(I_L) < n`.
 */
export function masterKeyFromSeed(seed: Uint8Array): HdNode {
  if (seed.length < 16 || seed.length > 64) {
    throw new Error(`Seed BIP-32 de longitud inválida: ${seed.length} bytes (admitido 16..64).`);
  }
130→  const { left, right } = hmac512(MASTER_KEY_SALT, seed);
  const k = parse256(left);
  if (k === 0n) throw new InvalidMasterKeyError('parse256(I_L) == 0');
  if (k >= SECP256K1_ORDER) throw new InvalidMasterKeyError('parse256(I_L) >= n');
  return { privateKey: left, chainCode: right };
}

/**
 * CKDpriv: clave privada hija a partir de la privada padre (HU-06-02 RN-3).
 *
140→ * - Hardened (`i >= 2³¹`): `I = HMAC-SHA512(c_par, 0x00 ‖ ser256(k_par) ‖ ser32(i))`.
 * - Normal   (`i <  2³¹`): `I = HMAC-SHA512(c_par, serP(point(k_par)) ‖ ser32(i))`.
 *
 * `k_hijo = (parse256(I_L) + k_par) mod n`, `c_hijo = I_R`. Si `parse256(I_L) >= n` o
 * `k_hijo == 0`, la clave es inválida y se lanza {@link InvalidChildKeyError} (RN-8).
 */
export function ckdPriv(node: HdNode, index: number): HdNode {
  if (!Number.isInteger(index) || index < 0 || index > MAX_INDEX) {
    throw new Error(`Índice BIP-32 fuera de rango: ${index}.`);
  }
150→
  const data =
    index >= HARDENED_OFFSET
      ? concat(new Uint8Array([0x00]), node.privateKey, ser32(index))
      : concat(serializedPoint(node.privateKey), ser32(index));

  const { left, right } = hmac512(node.chainCode, data);

  const il = parse256(left);
  if (il >= SECP256K1_ORDER) throw new InvalidChildKeyError(index, 'parse256(I_L) >= n');
160→
  const childKey = (il + parse256(node.privateKey)) % SECP256K1_ORDER;
  if (childKey === 0n) throw new InvalidChildKeyError(index, 'k_hijo == 0');

  return { privateKey: ser256(childKey), chainCode: right };
}

function concat(...parts: readonly Uint8Array[]): Uint8Array {
  const total = parts.reduce((acc, part) => acc + part.length, 0);
  const out = new Uint8Array(total);
170→  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/**
 * Parsea un path BIP-32 tipo `m/44'/60'/0'/0/0` a la lista de índices ya resueltos
180→ * (los componentes hardened suman `HARDENED_OFFSET`). Se aceptan `'` y `h`/`H` como
 * marca de hardened.
 */
export function parsePath(path: string): number[] {
  const trimmed = path.trim();
  const parts = trimmed.split('/');
  const head = parts[0];
  if (head !== 'm' && head !== 'M') {
    throw new Error(`Path BIP-32 inválido: "${path}" (debe empezar con "m").`);
  }
190→
  return parts.slice(1).map((component) => {
    const match = /^(\d+)(['hH])?$/u.exec(component);
    if (match === null) {
      throw new Error(`Path BIP-32 inválido: componente "${component}" en "${path}".`);
    }
    const value = Number(match[1]);
    if (!Number.isInteger(value) || value >= HARDENED_OFFSET) {
      throw new Error(`Path BIP-32 inválido: índice "${component}" fuera de rango en "${path}".`);
    }
200→    return match[2] === undefined ? value : value + HARDENED_OFFSET;
  });
}

/**
 * Deriva el nodo correspondiente a `path` desde la seed binaria. Función **pura** de
 * `(seed, path)`: mismas entradas ⇒ mismas salidas siempre (HU-06-02 RN-5, INV-8).
 */
export function derivePath(seed: Uint8Array, path: string): HdNode {
  const indexes = parsePath(path);
210→  let node = masterKeyFromSeed(seed);
  for (let depth = 1; depth <= indexes.length; depth += 1) {
    try {
      node = ckdPriv(node, indexes[depth - 1] as number);
    } catch (error) {
      // Se anota el nivel del path para que el llamador distinga un fallo en el último
      // componente (el `address_index`, recuperable avanzando al siguiente) de uno en un
      // componente intermedio del path BIP-44, que es fijo y por lo tanto irrecuperable.
      if (error instanceof InvalidChildKeyError) error.depth = depth;
      throw error;
220→    }
  }
  return node;
}

1→/**
 * Direcciones Ethereum: derivación desde la clave pública y checksum EIP-55.
 *
 * Fuente normativa: ERC-55 / EIP-55 («Mixed-case checksum address encoding») y Keccak-256.
 * Spec del proyecto: HU-06-02 RN-4 (dirección = últimos 20 bytes de `Keccak-256(X ‖ Y)`,
 * serializada como `0x` + 40 hex con checksum EIP-55) y RN-7 (uso en Sepolia; el formato
 * de dirección es agnóstico a la red).
 */
import { keccak_256 } from '@noble/hashes/sha3.js';
10→import { validationError } from '../../shared/errors.js';

/** `0x` + 40 dígitos hexadecimales, en cualquier capitalización. */
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/u;

/** Longitud en bytes de una dirección Ethereum (EOA de 20 bytes). */
export const ADDRESS_BYTES = 20;

const ascii = new TextEncoder();

20→function toHex(bytes: Uint8Array): string {
  let hex = '';
  for (const byte of bytes) hex += byte.toString(16).padStart(2, '0');
  return hex;
}

/** `true` si la cadena tiene la forma `0x` + 40 hex (sin mirar el checksum). */
export function isValidAddressFormat(address: string): boolean {
  return ADDRESS_RE.test(address);
}
30→
/**
 * Aplica el checksum EIP-55: `Keccak-256` sobre la cadena ASCII hexadecimal en
